const groups: Array<[LearningLanguage, LearningLevel, Draft[]]> = [
  ['de', 'A2', germanA2], ['de', 'B1', germanB1], ['en', 'A2', englishA2], ['en', 'B1', englishB1],
];

export const readingTexts: LongReadingText[] = groups.flatMap(([language, level, drafts]) =>
  drafts.map((draft, index) => {
    const { words, ...text } = draft;
    const continuations = language === 'de'
      ? level === 'A2' ? germanA2More : germanB1More
      : level === 'A2' ? englishA2More : englishB1More;
    const finales = language === 'de'
      ? level === 'A2' ? germanA2Finale : germanB1Finale
      : level === 'A2' ? englishA2Finale : englishB1Finale;
    return {
      id: `${language}-${level.toLowerCase()}-${index + 1}`,
      language,
      level,
      ...text,
      body: `${text.body}\n\n${continuations[index]}\n\n${finales[index]}`,
      difficultWords: words.map(([word, translation]) => ({ word, translation })),
    };
  }),
);

export function readingTextsFor(language: LearningLanguage, level: LearningLevel): LongReadingText[] {
  return readingTexts.filter((text) => text.language === language && text.level === level);
}
